pre.code:
struct Node {
    char val;
    Node *left, *right;
};

void preorder(Node *root) {
    if (root == nullptr) return;
    cout << root->val;      // 先访问根
    preorder(root->left);
    preorder(root->right);
}

void inorder(Node *root) {
    if (root == nullptr) return;
    inorder(root->left);
    cout << root->val;      // 中间访问根
    inorder(root->right);
}
